package server

const supporterHTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0b0d0b"><link rel="icon" href="/static/icon.svg?v=11"><title>Supporter badges · Kinosail Subtitles</title><script src="/static/theme.js?v=electric-1"></script><link rel="stylesheet" href="/static/app.css?v=electric-1"><script defer src="/static/main.kinosail.bundle.js?v=7"></script></head><body class="supporter-page"><a class="skip" href="#main">Skip to content</a><main id="main" class="supporter-shell"><a class="back" href="/settings">{{icon "back"}} Settings</a><header class="supporter-intro"><span class="eyebrow">Kinosail Subtitles supporter registry</span><h1>Two badge families. Every level has its own shape.</h1><p>Support stays voluntary. Kinosail Subtitles keeps every core feature. Monthly and one-time support both earn complete, app-specific badges.</p></header>
{{if .HasAny}}<section class="supporter-ledger" aria-labelledby="supporter-ledger-title"><header><span class="eyebrow">Your badge case</span><h2 id="supporter-ledger-title">Recognition stored on this Server</h2></header>{{if .HasMasterwork}}<article class="subtitle-masterwork{{if .MasterworkActive}} is-active{{else}} is-dormant{{end}}"><svg class="badge-sigil" viewBox="0 0 240 240" role="img" aria-label="Kinosail Subtitles Perfect Sync masterwork, level {{.Status.BadgeCase.MasterworkLevel}}"><path class="badge-outline" d="{{.Masterwork.Outline}}"/><path class="masterwork-wave" d="M38 92c28-24 54-24 82 0s54 24 82 0M38 148c28 24 54 24 82 0s54-24 82 0"/><path class="caption-frame masterwork-left" d="M48 76h76v62H82l-20 16v-16H48Z"/><path class="caption-frame masterwork-right" d="M116 102h76v62h-14v16l-20-16h-42Z"/><path class="caption-lines" d="M65 98h42M65 116h30M133 124h42M145 142h30"/></svg><div><span class="badge-rank">Perfect Sync · Level {{.Status.BadgeCase.MasterworkLevel}}</span><h3>{{t .Masterwork.BadgeName}}</h3><p>Both badge families meet here. Perfect Sync rises only when both families reach the next level.</p><strong>{{if .MasterworkActive}}Living cadence active{{else}}Earned permanently · Living cadence dormant{{end}}</strong></div></article>{{end}}<div class="supporter-ledger-grants">{{template "ownedGrant" .LivingStandard}}{{template "ownedGrant" .PatronOrder}}</div>{{if .HasAnyFleet}}<p class="fleet-note"><strong>Complete Fleet</strong> comes only from signed collection metadata. A Living Complete Fleet follows future configured apps while active. A dated Patron edition stays fixed.</p>{{end}}</section>{{end}}
{{if .Error}}<p class="supporter-error" role="alert">{{t .Error}}</p>{{end}}<section class="supporter-activation" aria-labelledby="activation-title"><div><span class="eyebrow">Optional local activation</span><h2 id="activation-title">Add or refresh either badge</h2><p>The Server sends only the key, app ID, and a random installation mark. It stores no payment details or supporter key. Signed results verify offline.</p></div><form method="post" action="/supporter/activate"><label>Supporter key<input name="key" required minlength="8" maxlength="128" pattern="[A-Za-z0-9_-]{8,128}" autocomplete="off" spellcheck="false"></label><label>Public recognition name <small>Optional. Levels 7–10 only. This name appears on shared certificates.</small><input name="recognitionName" maxlength="80" autocomplete="off"></label><button>Activate or refresh badge</button></form></section><aside class="supporter-fleet" aria-labelledby="complete-fleet-title"><span class="eyebrow">Complete Fleet</span><div><h2 id="complete-fleet-title">One key covers every included app.</h2><p>Each app keeps its own emblem and Share Certificate. Living follows current apps while active. Dated Patron editions stay fixed.</p></div></aside>
{{template "badgeFamily" .LivingStandard}}{{template "badgeFamily" .PatronOrder}}<section class="supporter-privacy" aria-labelledby="privacy-title"><span class="eyebrow">Private by default</span><h2 id="privacy-title">Share the honor, not the activation.</h2><p>Downloaded certificates include the app, badge family, level, dates, and an explicitly supplied high-level recognition name. They exclude keys, supporter marks, signatures, payment data, devices, and installation data.</p></section><footer><a href="/">Library</a><span>·</span><a href="/settings">Settings</a><span>·</span><a href="https://github.com/Kinosail/kinosail/blob/main/apps/subtitles/SUPPORTERS.md" rel="external noreferrer">Public supporters</a></footer></main><script src="/static/supporter.js?v=8"></script></body></html>
{{define "ownedGrant"}}<article class="owned-grant {{if .Status.Active}}is-active{{else if .Status.Archived}}is-archived{{end}}"><span>{{t .Status.Title}}</span>{{if .Available}}<h3>{{t .CurrentBadge.BadgeName}}</h3><p>Level {{.Status.Rank}} · {{t .Status.Name}}{{if .Status.Founding}} · Founding{{end}}</p>{{if .Status.RecognitionName}}<p>Shared as <strong>{{.Status.RecognitionName}}</strong></p>{{end}}<dl><div><dt>Supported since</dt><dd>{{.SupportedSince}}</dd></div>{{if .ExpiresAt}}<div><dt>{{if .Status.Archived}}Active through{{else}}Current through{{end}}</dt><dd>{{.ExpiresAt}}</dd></div>{{end}}</dl>{{if .Status.Collection}}<p class="fleet-mark"><strong>Complete Fleet · {{.Status.Collection.Edition}}</strong><span>{{len .Status.Collection.AppIDs}} apps in this signed edition</span></p>{{end}}{{if .Status.ServiceMarks}}<p class="service-marks" aria-label="Subscriber service marks">{{range .Status.ServiceMarks}}<span title="{{.}} months">{{.}}m</span>{{end}}</p>{{end}}<div class="certificate-actions"><a class="button quiet" download href="/api/v1/supporter/certificates/{{.ID}}">Download SVG certificate</a><button class="quiet share-certificate" type="button" data-certificate-url="/api/v1/supporter/certificates/{{.ID}}" data-certificate-name="kinosail-subtitles-{{.ID}}-{{.Status.Tier}}.png">Share PNG certificate</button></div><p class="share-status" role="status" aria-live="polite"></p>{{else}}<h3>Not activated</h3><p>Your other badge family stays independent.</p>{{end}}</article>{{end}}
{{define "badgeFamily"}}<section class="supporter-family family-{{.ID}}{{if .Status.Archived}} family-archived{{end}}" aria-labelledby="{{.ID}}-title"><header><div><span class="eyebrow">{{t .Eyebrow}}</span><h2 id="{{.ID}}-title">{{t .FamilyTitle}}</h2><p>{{t .Intro}}</p></div><a class="family-purchase" href="{{.SupportURL}}" rel="external noreferrer">{{t .PurchaseLabel}}</a></header><ol class="badge-gallery">{{range .Tiers}}<li class="badge-level{{if .Elite}} elite{{end}}{{if .Current}} current{{else if .Collected}} collected{{end}}" data-rank="{{.Rank}}"><img class="badge-sigil" width="360" height="360" src="/static/supporter/badges/{{$.ID}}-{{.Rank}}.svg?v=1" alt="Level {{.Rank}} {{t .BadgeName}} badge for Kinosail Subtitles" decoding="async"><span class="badge-rank">Level {{.Rank}}</span><h3>{{t .BadgeName}}</h3><p>{{t .Detail}}</p><small>{{if .Elite}}Elite level · {{end}}{{if .Current}}{{if $.Status.Archived}}Archived{{else}}Yours{{end}}{{else if .Collected}}Collected{{else}}Available{{end}}</small></li>{{end}}</ol></section>{{end}}`

var supporterView = newLocalizedTemplate("supporter", supporterHTML)
